import type { CSSObject } from '@emotion/react';

/** Maps prop values to Emotion style objects. Use `$`-prefixed transient prop names. */
export type VariantDefinitions = Record<string, Record<string, CSSObject>>;

function toVariantKey(value: unknown): string | undefined {
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }

  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    return `${value}`;
  }

  return undefined;
}

export function applyVariants(
  props: object,
  definitions: VariantDefinitions,
): CSSObject {
  const propRecord = props as Record<string, unknown>;

  return Object.entries(definitions).reduce<CSSObject>(
    (styles, [propName, variantMap]) => {
      const variantKey = toVariantKey(propRecord[propName]);

      if (variantKey === undefined) {
        return styles;
      }

      const variantStyles = variantMap[variantKey];

      if (!variantStyles) {
        return styles;
      }

      return { ...styles, ...variantStyles };
    },
    {},
  );
}

export function withVariantStyles(definitions: VariantDefinitions) {
  return (props: object) => applyVariants(props, definitions);
}

/** Base styles + variant map — use as the single callback for `emotionStyled(Component)`. */
export function composeStyles<P extends object>(
  base: CSSObject,
  definitions: VariantDefinitions,
) {
  return (props: P): CSSObject => ({
    ...base,
    ...applyVariants(props, definitions),
  });
}
